const formatter=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Windhoek',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',weekday:'short',hourCycle:'h23'});
export function namibiaTime(now=Date.now()){const date=new Date(now),p=Object.fromEntries(formatter.formatToParts(date).map(p=>[p.type,p.value]));return {hour:Number(p.hour),minute:Number(p.minute),second:Number(p.second),weekday:p.weekday,date:p.year+'-'+p.month+'-'+p.day,label:p.hour+':'+p.minute+' CAT',weekend:['Sat','Sun'].includes(p.weekday)};}
const rad=Math.PI/180,clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export function daylight(now=Date.now()){const d=new Date(now),n=Math.floor((Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate())-Date.UTC(d.getUTCFullYear(),0,0))/86400000),h=d.getUTCHours()+d.getUTCMinutes()/60,g=2*Math.PI/365*(n-1+(h-12)/24),eq=229.18*(.000075+.001868*Math.cos(g)-.032077*Math.sin(g)-.014615*Math.cos(2*g)-.040849*Math.sin(2*g)),dec=.006918-.399912*Math.cos(g)+.070257*Math.sin(g)-.006758*Math.cos(2*g)+.000907*Math.sin(2*g)-.002697*Math.cos(3*g)+.00148*Math.sin(3*g),angle=((h*60+eq+4*17.08+1440)%1440/4-180)*rad,lat=-22.56*rad,altitude=Math.asin(Math.sin(lat)*Math.sin(dec)+Math.cos(lat)*Math.cos(dec)*Math.cos(angle))/rad,light=clamp((altitude+7)/18,0,1),smooth=light*light*(3-2*light);return {altitude,light:smooth,lamps:1-clamp((altitude+4)/8,0,1),azimuth:angle,phase:altitude>5?'Day':altitude>-6?'Twilight':'Night'};}
export function residentActivity(role,key,time=namibiaTime()){const hour=time.hour+time.minute/60,offset=[...String(key)].reduce((n,c)=>n+c.charCodeAt(0),0);if(role==='child'){if(hour<6.5||hour>=20)return 'sleep';if(!time.weekend&&hour>=7.5&&hour<13)return 'school';return hour>=9&&hour<18.5&&(time.minute+offset)%10<5?'play':'home';}if(hour<6||hour>=21)return 'sleep';return hour>=8&&hour<18&&(time.minute+offset)%12<6?'errand':'work';}
